\question{1}{8} Find the values of the following expressions.

\begin{subparts}
  \item $\left[\left(+\dfrac{1}{6}\right)-\left(+\dfrac{4}{5}\right)+\left(-\dfrac{5}{6}\right)\right]\times(-15)$

  \item $\left[\left(-1\dfrac{1}{4}\right)-\left(-\dfrac{1}{2}\right)\right]\div\left[(-3)-\left(-6\dfrac{1}{3}\right)\right]$
\end{subparts}

\answerlines{17}

\msquestion{1}{8}
\begin{mspart}{(a)}
  \msexpr{\left[\left(+\dfrac{1}{6}\right)-\left(+\dfrac{4}{5}\right)+\left(-\dfrac{5}{6}\right)\right]\times(-15)}
  \msstep{=\left(\dfrac{1}{6}-\dfrac{5}{6}-\dfrac{4}{5}\right)\times(-15)}{1M}
  \msstep{=\left(-\dfrac{2}{3}-\dfrac{4}{5}\right)\times(-15)}{1M}
  \msstep{=\left(-\dfrac{22}{15}\right)\times(-15)}{1M}
  \msstep{=22}{1A}
\end{mspart}
\begin{mspart}{(b)}
  \msexpr{\left[\left(-1\dfrac{1}{4}\right)-\left(-\dfrac{1}{2}\right)\right]\div\left[(-3)-\left(-6\dfrac{1}{3}\right)\right]}
  \msstep{=\left(-\dfrac{5}{4}+\dfrac{1}{2}\right)\div\left(-3+\dfrac{19}{3}\right)}{1M}
  \msstep{=\left(-\dfrac{3}{4}\right)\div\left(\dfrac{10}{3}\right)}{1M}
  \msstep{=-\dfrac{9}{40}}{1M+1A}
\end{mspart}

