\question{1}{8} Find the values of the following expressions.

\begin{subparts}
  \item $\dfrac{[(-5.6)+(+2)]\times(-3)}{(-6)}-(-4)$

  \item $5-\dfrac{[(-2)-(+8)]\times(-2.5)}{(-5)}$
\end{subparts}

\answerlines{16}

\msquestion{1}{8}
\begin{mspart}{(a)}
  \msexpr{\dfrac{[(-5.6)+(+2)]\times(-3)}{(-6)}-(-4)}
  \msstep{=\dfrac{(-3.6)\times(-3)}{(-6)}-(-4)}{1M}
  \msstep{=\dfrac{10.8}{(-6)}-(-4)}{1M}
  \msstep{=-1.8+4}{1M}
  \msstep{=2.2}{1A}
\end{mspart}
