  \msexpr{5-\dfrac{[(-2)-(+8)]\times(-2.5)}{(-5)}}
  \msstep{=5-\dfrac{(-10)\times(-2.5)}{(-5)}}{1M}
  \msstep{=5-\dfrac{25}{(-5)}}{1M}
  \msstep{=5+5}{1M}
  \msstep{=10}{1A}
\end{mspart}

