\question{3}{5} The following shows a sequence of figures formed by sticks. The 1st figure has $5$ sticks. The 2nd figure has $11$ sticks. The 3rd figure has $19$ sticks. The 4th figure has $29$ sticks, and so on.

\par\vspace{0.5em}
\noindent\textbf{Figures:}\quad
\begin{tikzpicture}[scale=0.38,baseline=-0.6ex,every node/.style={font=\small}]
  \foreach \f/\x/\n in {1/0/1, 2/4.2/2, 3/9.4/3, 4/15.6/4} {
    \foreach \i in {0,...,\n} {
      \draw (\x+\i*0.55,0) -- (\x+\i*0.55,\n*0.55);
    }
    \foreach \j in {0,...,\n} {
      \draw (\x,\j*0.55) -- (\x+\n*0.55,\j*0.55);
    }
    \ifnum\f=1 \def\flabel{1st}\fi
    \ifnum\f=2 \def\flabel{2nd}\fi
    \ifnum\f=3 \def\flabel{3rd}\fi
    \ifnum\f=4 \def\flabel{4th}\fi
    \node[below] at (\x+\n*0.55/2,-0.35) {\flabel};
  }
\end{tikzpicture}

\begin{subparts}
  \item According to the above pattern, guess the number of sticks used to form the 5th figure and explain your answer.
  \item A student claims that the number of sticks used to form the 6th figure is an odd number. Do you agree? Explain your answer.
\end{subparts}

\answerlines{14}

\msquestion{3}{5}
\begin{mspart}{(a)}
  \msstep{11-5=6,\quad19-11=8,\quad29-19=10}{1M}
  \msstep{\text{The increases are 6, 8 and 10, so the next increase is 12.}}{1M}
  \msstep{\text{5th figure}=29+12=41}{1A}
\end{mspart}
\begin{mspart}{(b)}
  \msstep{\text{The next increase is 14.}}{1M}
  \msstep{\text{6th figure}=41+14=55}{1A}
  \msstep{\text{Yes. 55 is an odd number.}}{1A}
\end{mspart}

\question{4}{6} The length, width and height of Kevin's bedroom are $4a$ m, $3a$ m and $3$ m respectively. Kevin is going to paint the rectangular ceiling and four rectangular walls of his bedroom. A window of area $\dfrac{a}{2}\,\text{m}^2$ and a door of area $\dfrac{7a}{2}\,\text{m}^2$ which are built on the walls will not be painted.

\begin{subparts}
  \item Express the total painted area in terms of $a$.
  \item If $a=2$ and the cost of painting is $\$50/\text{m}^2$, can Kevin paint his bedroom at a cost of not more than $\$6500$? Explain your answer.
\end{subparts}

\answerlines{14}

\msquestion{4}{6}
\begin{mspart}{(a)}
  \msstep{\text{Ceiling}=4a\times3a=12a^2}{1M}
  \msstep{\text{Walls}=2(4a)(3)+2(3a)(3)=24a+18a=42a}{1M}
  \msstep{\text{Painted area}=12a^2+42a-\dfrac{a}{2}-\dfrac{7a}{2}}{1M}
  \msstep{=12a^2+38a\text{ m}^2}{1A}
\end{mspart}
\begin{mspart}{(b)}
  \msstep{\text{When }a=2,\ \text{painted area}=12(2^2)+38(2)=124\text{ m}^2}{1M}
  \msstep{\text{Cost}=124\times50=\$6200}{1M}
  \msstep{\text{Yes. Since }\$6200\le\$6500,\ \text{Kevin can paint his bedroom at a cost of not more than }\$6500.}{1A}
\end{mspart}

